public static ECKey vanity(String prefix, Network network) {
    String target = (network == BitcoinNetwork.MAINNET ? "1" : "m") + prefix;  // testnet: 'm' o 'n'
    long tries = 0;
    while (true) {
        tries++;
        ECKey key = new ECKey();                               // chiave casuale
        String addr = key.toAddress(ScriptType.P2PKH, network).toString();
        if (addr.startsWith(target)) {
            System.out.println(tries + " tentativi: " + addr);
            return key;                                        // la chiave privata va conservata!
        }
    }
}

