# richiede: pip install ecdsa pycryptodome
import hashlib
from ecdsa import SigningKey, SECP256k1

B58 = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"

def sha256(b): return hashlib.sha256(b).digest()
def ripemd160(b):
    try:
        return hashlib.new("ripemd160", b).digest()
    except ValueError:                      # OpenSSL 3 può non averlo
        from Crypto.Hash import RIPEMD160
        return RIPEMD160.new(b).digest()
def hash160(b): return ripemd160(sha256(b))

def b58encode(b):
    n = int.from_bytes(b, "big"); s = ""
    while n:
        n, r = divmod(n, 58); s = B58[r] + s
    return "1" * (len(b) - len(b.lstrip(b"\0"))) + s

def base58check(version, payload):
    raw = bytes([version]) + payload
    return b58encode(raw + sha256(sha256(raw))[:4])

def p2pkh(pub, mainnet=True):
    return base58check(0x00 if mainnet else 0x6F, hash160(pub))

if __name__ == "__main__":
    sk = SigningKey.from_secret_exponent(1, curve=SECP256k1)
    pub = sk.get_verifying_key().to_string("compressed")
    print("pubkey compressa:", pub.hex())
    print("testnet P2PKH:", p2pkh(pub, False))
    print("mainnet P2PKH:", p2pkh(pub, True))
    pub_u = sk.get_verifying_key().to_string("uncompressed")
    print("mainnet P2PKH (pubkey non compressa):", p2pkh(pub_u, True))

CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"

def polymod(values):
    GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3]
    chk = 1
    for v in values:
        b = chk >> 25
        chk = (chk & 0x1ffffff) << 5 ^ v
        for i in range(5):
            chk ^= GEN[i] if (b >> i) & 1 else 0
    return chk

def hrp_expand(hrp):
    return [ord(x) >> 5 for x in hrp] + [0] + [ord(x) & 31 for x in hrp]

def convertbits(data, frombits, tobits):
    acc = bits = 0; out = []; maxv = (1 << tobits) - 1
    for d in data:
        acc = (acc << frombits) | d; bits += frombits
        while bits >= tobits:
            bits -= tobits; out.append((acc >> bits) & maxv)
    if bits:
        out.append((acc << (tobits - bits)) & maxv)
    return out

def segwit_address(hrp, witver, program):
    data = [witver] + convertbits(program, 8, 5)
    const = 1 if witver == 0 else 0x2bc830a3       # bech32 (v0) / bech32m (v1+, Taproot)
    pm = polymod(hrp_expand(hrp) + data + [0] * 6) ^ const
    checksum = [(pm >> 5 * (5 - i)) & 31 for i in range(6)]
    return hrp + "1" + "".join(CHARSET[d] for d in data + checksum)

h160 = bytes.fromhex("751e76e8199196d454941c45d1b3a323f1433bd6")   # hash160 della pubkey di sk=1
a = segwit_address("bc", 0, h160)
print(a, a == "bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4")
print(segwit_address("tb", 0, h160))
print(segwit_address("bc", 1, bytes(32))[:6], "<- versione 1 (32 byte): prefisso di un P2TR")
